+++ b/src/index.js
 // QueenOS worker-starter: a dependency-free router. No build step: every
 // src/**/*.js file is uploaded as an ES module, so imports must be relative.
 import { features } from "./features/index.js";

 const json = (body, status = 200) =>
   new Response(JSON.stringify(body, null, 2) + "\n", {
     status,
     headers: { "content-type": "application/json; charset=utf-8" },
   });

+const html = (body, status = 200) =>
+  new Response(body, {
+    status,
+    headers: { "content-type": "text/html; charset=utf-8" },
+  });
+
+const statusPage = (app, features) => `<!doctype html>
+<html lang="en">
+<head>
+<meta charset="utf-8" />
+<meta name="viewport" content="width=device-width, initial-scale=1" />
+<title>${app} — Status</title>
+<style>
+  :root { color-scheme: light dark; }
+  * { box-sizing: border-box; }
+  body { margin: 0; font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; background: #f4f6f8; color: #1c2733; display: grid; place-items: center; min-height: 100vh; padding: 1rem; }
+  .card { background: #fff; border-radius: 16px; box-shadow: 0 10px 25px rgba(0,0,0,.08); padding: 2rem 2.5rem; max-width: 480px; width: 100%; }
+  .status { display: inline-flex; align-items: center; gap: .5rem; font-weight: 700; color: #0f7a3d; }
+  .dot { width: 12px; height: 12px; border-radius: 50%; background: #21a35c; box-shadow: 0 0 0 4px rgba(33,163,92,.2); }
+  h1 { font-size: 1.5rem; margin: .75rem 0 .25rem; }
+  p { margin: .25rem 0; color: #5b6b7b; }
+  ul { margin: 1rem 0 0; padding-left: 1.25rem; color: #1c2733; }
+  li { margin: .3rem 0; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }
+  .meta { margin-top: 1.5rem; border-top: 1px solid #e5e9ed; padding-top: 1rem; font-size: .9rem; display: grid; gap: .4rem; }
+  .meta div { display: flex; justify-content: space-between; gap: 1rem; }
+  .meta span:first-child { color: #8a99a8; }
+</style>
+</head>
+<body>
+  <main class="card">
+    <div class="status"><span class="dot"></span> All systems operational</div>
+    <h1>${app} Status</h1>
+    <p>Everything is healthy and running smoothly.</p>
+    <ul>
+      ${features.map((slug) => `<li>${slug}</li>`).join("")}
+    </ul>
+    <div class="meta">
+      <div><span>Features</span><span>${features.length}</span></div>
+      <div><span>Checked at</span><span>${new Date().toISOString()}</span></div>
+    </div>
+  </main>
+</body>
+</html>`;
+
 export default {
   async fetch(request) {
     const url = new URL(request.url);
     try {
       // Feature guards run on every request (auth, flags, rate limits, ...).
       for (const feature of features) {
         if (typeof feature.guard === "function") await feature.guard(request);
       }

       if (url.pathname === "/" || url.pathname === "") {
+        return html(statusPage("worker-starter", features.map((f) => f.slug)));
-        return json({ ok: true, app: "worker-starter", features: features.map((f) => f.slug) });
       }
       if (url.pathname === "/health") return json({ ok: true });

       const match = /^\/features\/([a-z0-9-]+)\/?$/.exec(url.pathname);
       if (match) {
         const feature = features.find((f) => f.slug === match[1]);
         if (feature) return await feature.handle(request);
       }
       return json({ ok: false, error: "not found", path: url.pathname }, 404);
     } catch (err) {
       return json({ ok: false, error: String((err && err.message) || err) }, 500);
     }
   },
 };

